import type { AxiosInstance } from 'axios';
import type { FrigateAdapterConfig, FrigateMessage } from '../types.js';
import { removePathData } from './messageHandler.js';
import type Json2iob from './json2iob.js';

interface EventHistoryContext {
    adapter: ioBroker.Adapter & { config: FrigateAdapterConfig; frigateBaseUrl: string };
    requestClient: AxiosInstance;
    json2iob: Json2iob;
    deviceArray: string[];
}

/**
 * Whether the history of every camera is kept in `<camera>.history` as well as in `events.history`.
 *
 * @param config the adapter settings; settings from before the option have it not and mean on
 */
function historyPerCamera(config: FrigateAdapterConfig): boolean {
    return config.historyPerCamera !== false;
}

/**
 * Whether each event of the history is written as single states, not only as JSON.
 *
 * @param config the adapter settings; settings from before the option have it not and mean on
 */
function historyStates(config: FrigateAdapterConfig): boolean {
    return config.historyStates !== false;
}

/**
 * Reads the last events from Frigate into `events.history` (all cameras) and `<camera>.history`.
 *
 * Each list is written as JSON (`<path>.json`) and, unless `historyStates` is off, as single states.
 * Only values that differ from the last fetch are written: the history is fetched again after every
 * event, and mostly nothing in it has changed. Writing everything again flooded the controller and
 * every adapter subscribed to all states with thousands of unchanged values.
 * Values the new data does not have any more are set to null, so no old event shows through.
 *
 * @param ctx adapter, client and the known cameras
 * @param devices cameras to fetch, '' for the history of all cameras; default: all known ones. The
 *     cameras are skipped when `historyPerCamera` is off
 */
export async function fetchEventHistory(ctx: EventHistoryContext, devices: string[] = ctx.deviceArray): Promise<void> {
    const perCamera = historyPerCamera(ctx.adapter.config);
    const asStates = historyStates(ctx.adapter.config);
    for (const device of devices) {
        if (device && !perCamera) {
            continue;
        }
        const params: { limit: number; cameras?: string } = { limit: ctx.adapter.config.webnum as number };
        if (device) {
            params.cameras = device;
        }
        try {
            const response = await ctx.requestClient({
                url: `${ctx.adapter.frigateBaseUrl}/api/events`,
                method: 'get',
                params,
            });
            if (response.data) {
                ctx.adapter.log.debug(`fetchEventHistory successful ${device}`);

                for (const event of response.data) {
                    event.websnap = `${ctx.adapter.frigateBaseUrl}/api/events/${event.id}/snapshot.jpg`;
                    event.webclip = `${ctx.adapter.frigateBaseUrl}/api/events/${event.id}/clip.mp4`;
                    event.webm3u8 = `${ctx.adapter.frigateBaseUrl}/vod/event/${event.id}/master.m3u8`;
                    // Up to Frigate 0.13 the thumbnail came as base64. Since 0.14 Frigate keeps it as a
                    // file and sends null, which made "data:image/jpeg;base64,null" - a broken picture
                    event.thumbnail = event.thumbnail
                        ? `data:image/jpeg;base64,${event.thumbnail}`
                        : `${ctx.adapter.frigateBaseUrl}/api/events/${event.id}/thumbnail.jpg`;
                    delete event.path_data;
                }
                const path = device ? `${device}.history` : 'events.history';
                removePathData(response.data);

                if (asStates) {
                    const written = new Set<string>();
                    await ctx.json2iob.parse(path, response.data, {
                        forceIndex: true,
                        channelName: 'Events history',
                        onlyChanged: true,
                        writtenIds: written,
                    });
                    // The entries are numbered by position: without this, a field the new event at a
                    // position does not have (e.g. no sub_label) kept the value of the event before, and
                    // the positions beyond a shorter list kept old events
                    const cleared = await ctx.json2iob.clearStatesNotWritten(path, written, [`${path}.json`]);
                    if (cleared) {
                        ctx.adapter.log.debug(`Cleared ${cleared} outdated values in ${path}`);
                    }
                }
                await ctx.json2iob.setStateIfChanged(`${path}.json`, JSON.stringify(response.data));
            }
        } catch (error: any) {
            ctx.adapter.log.warn(`fetchEventHistory error from ${ctx.adapter.frigateBaseUrl}/api/events`);
            if (error.response && error.response.status >= 500) {
                ctx.adapter.log.warn('Cannot reach server. You can ignore this after restarting the frigate server.');
            }
            ctx.adapter.log.warn(error instanceof Error ? error.message : String(error));
        }
    }
}

export async function createCameraDevices(ctx: EventHistoryContext): Promise<any> {
    ctx.adapter.log.info('Create Device information and fetch Event History');
    const data = await ctx
        .requestClient({
            url: `${ctx.adapter.frigateBaseUrl}/api/config`,
            method: 'get',
        })
        .then(response => {
            ctx.adapter.log.debug(JSON.stringify(response.data));
            return response.data;
        })
        .catch(error => {
            ctx.adapter.log.warn(`createCameraDevices error from ${ctx.adapter.frigateBaseUrl}/api/config`);
            ctx.adapter.log.error(error instanceof Error ? error.message : String(error));
            error.response && ctx.adapter.log.error(JSON.stringify(error.response.data));
        });
    if (!data) {
        return;
    }

    const perCamera = historyPerCamera(ctx.adapter.config);
    await ctx.adapter.extendObjectAsync('events.history', {
        type: 'channel',
        common: { name: 'Events history' },
        native: {},
    });
    if (data.cameras) {
        for (const key in data.cameras) {
            ctx.deviceArray.push(key);
            ctx.adapter.log.info(`Create device information for: ${key}`);
            await ctx.adapter.extendObjectAsync(key, {
                type: 'device',
                common: { name: `Camera ${key}` },
                native: {},
            });
            if (perCamera) {
                await ctx.adapter.extendObjectAsync(`${key}.history`, {
                    type: 'channel',
                    common: { name: 'Event History' },
                    native: {},
                });
                await ctx.adapter.extendObjectAsync(`${key}.history.json`, {
                    type: 'state',
                    common: {
                        name: 'Events history',
                        role: 'json',
                        type: 'string',
                        read: true,
                        write: false,
                    },
                    native: {},
                });
            }
            await ctx.adapter.extendObjectAsync(`${key}.remote`, {
                type: 'channel',
                common: { name: 'Control camera' },
                native: {},
            });
            const remoteStates: { id: string; common: ioBroker.StateCommon }[] = [
                {
                    id: 'createEvent',
                    common: {
                        name: 'Create Event with label',
                        type: 'string',
                        role: 'text',
                        def: 'Label',
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'createEventBody',
                    common: {
                        name: 'Body for create Event',
                        type: 'string',
                        role: 'object',
                        def: '{}',
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'pauseNotifications',
                    common: {
                        name: 'Pause Camera notifications',
                        type: 'boolean',
                        role: 'switch',
                        def: false,
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'pauseNotificationsForTime',
                    common: {
                        name: 'Pause All notifications for time in minutes',
                        type: 'number',
                        role: 'value',
                        def: 10,
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'notificationText',
                    common: {
                        name: 'Overwrite the notification text',
                        type: 'string',
                        role: 'text',
                        def: '',
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'notificationMinScore',
                    common: {
                        name: 'Overwrite notification min score',
                        type: 'number',
                        role: 'value',
                        def: 0,
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'ptz',
                    common: {
                        name: 'Send PTZ commands preset_preset1, MOVE_LEFT, ZOOM_IN, STOP etc See docu',
                        desc: 'https://docs.frigate.video/integrations/mqtt/#frigatecamera_nameptz',
                        type: 'string',
                        role: 'text',
                        def: 'preset_preset1',
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'motionThreshold',
                    common: {
                        name: 'Motion detection threshold (1-255)',
                        type: 'number',
                        role: 'level',
                        def: 30,
                        min: 1,
                        max: 255,
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'motionContourArea',
                    common: {
                        name: 'Motion contour area minimum size',
                        type: 'number',
                        role: 'level',
                        def: 10,
                        min: 0,
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'birdseyeMode',
                    common: {
                        name: 'Birdseye viewing mode (objects, continuous, motion)',
                        type: 'string',
                        role: 'text',
                        def: 'objects',
                        states: { objects: 'objects', continuous: 'continuous', motion: 'motion' },
                        read: true,
                        write: true,
                    },
                },
                {
                    id: 'improveContrast',
                    common: {
                        name: 'Improve contrast for detection',
                        type: 'boolean',
                        role: 'switch',
                        def: false,
                        read: true,
                        write: true,
                    },
                },
            ];
            for (const s of remoteStates) {
                await ctx.adapter.extendObjectAsync(`${key}.remote.${s.id}`, {
                    type: 'state',
                    common: s.common,
                    native: {},
                });
            }
        }
    } else {
        ctx.adapter.log.warn('No cameras found');
        ctx.adapter.log.info(JSON.stringify(data));
    }
    const cameras = ctx.deviceArray.filter(device => device);
    await cleanEventHistoryObjects(ctx, cameras);
    if (perCamera) {
        ctx.adapter.log.info(`Fetch event history for ${cameras.length} cameras`);
    } else {
        ctx.adapter.log.info('Fetch event history (not per camera)');
    }
    await fetchEventHistory(ctx);
    ctx.adapter.log.info('Device information created');
    return data;
}

/**
 * Deletes the objects of the event history that the settings do not ask for (any more): the single
 * states when only the JSON is wanted (`historyStates` off), the whole history of each camera when
 * only the overall one is wanted (`historyPerCamera` off).
 *
 * Each event takes about 34 objects, and there are (cameras + 1) x `webnum` of them, which brought
 * installations with many cameras over the warn limit of the controller (5000 objects per instance).
 *
 * @param ctx the adapter
 * @param cameras names of the cameras
 */
export async function cleanEventHistoryObjects(
    ctx: Pick<EventHistoryContext, 'adapter'>,
    cameras: string[],
): Promise<void> {
    const asStates = historyStates(ctx.adapter.config);
    const lists: { path: string; keepJson: boolean }[] = [];
    if (!asStates) {
        lists.push({ path: 'events.history', keepJson: true });
    }
    for (const camera of cameras) {
        if (!historyPerCamera(ctx.adapter.config)) {
            lists.push({ path: `${camera}.history`, keepJson: false });
        } else if (!asStates) {
            lists.push({ path: `${camera}.history`, keepJson: true });
        }
    }
    for (const { path, keepJson } of lists) {
        const deleted = await deleteHistoryObjects(ctx.adapter, path, keepJson);
        if (deleted) {
            ctx.adapter.log.info(`Deleted ${deleted} objects of the event history in ${path}`);
        }
    }
}

/**
 * Deletes the states and channels below `path`.
 *
 * @param adapter the adapter
 * @param path the history, e.g. `events.history`
 * @param keepJson keep `<path>` and `<path>.json`, otherwise they are deleted as well
 * @returns the number of deleted objects
 */
async function deleteHistoryObjects(adapter: ioBroker.Adapter, path: string, keepJson: boolean): Promise<number> {
    const prefix = `${adapter.namespace}.`;
    const ids: string[] = [];
    try {
        for (const type of ['state', 'channel'] as const) {
            const view = await adapter.getObjectViewAsync('system', type, {
                startkey: `${prefix}${path}.`,
                endkey: `${prefix}${path}.香`,
            });
            for (const row of view?.rows || []) {
                const id = row.id.substring(prefix.length);
                if (!keepJson || id !== `${path}.json`) {
                    ids.push(id);
                }
            }
        }
        if (!keepJson && (await adapter.getObjectAsync(path))) {
            ids.push(path);
        }
    } catch (error) {
        adapter.log.warn(
            `Cannot read the objects below ${path}: ${error instanceof Error ? error.message : String(error)}`,
        );
        return 0;
    }
    let deleted = 0;
    for (const id of ids) {
        try {
            await adapter.delObjectAsync(id);
            deleted++;
        } catch (error) {
            adapter.log.debug(`Cannot delete ${id}: ${error instanceof Error ? error.message : String(error)}`);
        }
    }
    return deleted;
}

/**
 * Names in Frigate's face library, so `sub_labels.<name>` exists before somebody is recognized for
 * the first time and automations can be set up in advance.
 *
 * `/api/faces` answers `{ <name>: [<image files>] }`. The folder `train` holds recent recognitions
 * that nobody has assigned yet, so it is no name. Without face recognition in the Frigate config the
 * library is not asked at all.
 *
 * @param ctx adapter and the authenticated client for the Frigate API
 * @param ctx.adapter the adapter, for the base URL and the log
 * @param ctx.requestClient the client for the Frigate API
 * @param configData the answer of `/api/config`
 */
export async function fetchFaceNames(
    ctx: Pick<EventHistoryContext, 'adapter' | 'requestClient'>,
    configData: any,
): Promise<string[]> {
    if (configData?.face_recognition?.enabled !== true) {
        return [];
    }
    const url = `${ctx.adapter.frigateBaseUrl}/api/faces`;
    try {
        const response = await ctx.requestClient.get(url);
        const faces = response.data;
        if (!faces || typeof faces !== 'object' || Array.isArray(faces)) {
            ctx.adapter.log.warn(`Unexpected answer from ${url}: ${JSON.stringify(faces).substring(0, 200)}`);
            return [];
        }
        const names = Object.keys(faces).filter(name => name.trim() && name !== 'train');
        ctx.adapter.log.debug(`Face library: ${names.join(', ') || 'empty'}`);
        return names;
    } catch (error) {
        ctx.adapter.log.warn(`Cannot read the face library from ${url}`);
        ctx.adapter.log.warn(error instanceof Error ? error.message : String(error));
        return [];
    }
}

export async function cleanTrackedObjects(adapter: ioBroker.Adapter): Promise<void> {
    adapter.log.info('Cleaning old tracked objects');
    try {
        const objects = await adapter.getObjectListAsync({
            startkey: `${adapter.namespace}.tracked_objects.`,
            endkey: `${adapter.namespace}.tracked_objects.\u9999`,
        });
        for (const obj of objects.rows) {
            if (
                obj.id !== `${adapter.namespace}.tracked_objects` &&
                obj.id !== `${adapter.namespace}.tracked_objects.history`
            ) {
                try {
                    await adapter.delObjectAsync(obj.id.replace(`${adapter.namespace}.`, ''), { recursive: true });
                } catch {
                    // Continue if deletion fails
                }
            }
        }
        adapter.log.info('Cleaned all tracked objects');
    } catch (error) {
        adapter.log.warn(`Error cleaning tracked objects: ${error instanceof Error ? error.message : String(error)}`);
    }
}

export async function handleTrackedObjectUpdate(
    adapter: ioBroker.Adapter,
    trackedObjectsHistory: FrigateMessage[],
    data: FrigateMessage,
): Promise<FrigateMessage[]> {
    try {
        if (!data) {
            adapter.log.warn('Invalid tracked object update: no data');
            return trackedObjectsHistory;
        }
        adapter.log.debug(`Processing tracked object update: ${JSON.stringify(data).substring(0, 200)}...`);
        data.timestamp ||= Date.now() / 1000;
        trackedObjectsHistory.unshift(data);
        if (trackedObjectsHistory.length > 10) {
            trackedObjectsHistory = trackedObjectsHistory.slice(0, 10);
        }
        await adapter.setStateAsync('tracked_objects.history', JSON.stringify(trackedObjectsHistory), true);
        adapter.log.debug(`Stored tracked object update. History now contains ${trackedObjectsHistory.length} entries`);
    } catch (error) {
        adapter.log.error(
            `Error handling tracked object update: ${error instanceof Error ? error.message : String(error)}`,
        );
        adapter.log.error(error instanceof Error ? (error.stack ?? '') : String(error));
    }
    return trackedObjectsHistory;
}
